--- a/src/lib.rs
+++ b/src/lib.rs
@@ -1 +1,259 @@
-pub fn placeholder() {}
+use std::fmt;
+use std::fs;
+use std::path::{Path, PathBuf};
+
+#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
+pub struct Date {
+    year: u32,
+    month: u32,
+    day: u32,
+}
+
+impl Date {
+    pub fn new(year: u32, month: u32, day: u32) -> Result<Self, CalendarError> {
+        if year == 0 || year > 9999 {
+            return Err(CalendarError::InvalidDate);
+        }
+        if month == 0 || month > 12 {
+            return Err(CalendarError::InvalidDate);
+        }
+        if day == 0 || day > days_in_month(year, month) {
+            return Err(CalendarError::InvalidDate);
+        }
+        Ok(Self { year, month, day })
+    }
+
+    pub fn parse(input: &str) -> Result<Self, CalendarError> {
+        let bytes = input.as_bytes();
+        if bytes.len() != 10 || bytes[4] != b'-' || bytes[7] != b'-' {
+            return Err(CalendarError::InvalidDate);
+        }
+        let year = parse_digits(&bytes[0..4]).ok_or(CalendarError::InvalidDate)?;
+        let month = parse_digits(&bytes[5..7]).ok_or(CalendarError::InvalidDate)?;
+        let day = parse_digits(&bytes[8..10]).ok_or(CalendarError::InvalidDate)?;
+        Self::new(year, month, day)
+    }
+
+    pub fn year(&self) -> u32 {
+        self.year
+    }
+
+    pub fn month(&self) -> u32 {
+        self.month
+    }
+
+    pub fn day(&self) -> u32 {
+        self.day
+    }
+}
+
+impl fmt::Display for Date {
+    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
+        write!(f, "{:04}-{:02}-{:02}", self.year, self.month, self.day)
+    }
+}
+
+pub fn days_in_month(year: u32, month: u32) -> u32 {
+    match month {
+        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
+        4 | 6 | 9 | 11 => 30,
+        2 if is_leap_year(year) => 29,
+        2 => 28,
+        _ => 0,
+    }
+}
+
+pub fn is_leap_year(year: u32) -> bool {
+    year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)
+}
+
+fn parse_digits(bytes: &[u8]) -> Option<u32> {
+    let mut value = 0u32;
+    for byte in bytes {
+        if !byte.is_ascii_digit() {
+            return None;
+        }
+        let digit = *byte - b'0';
+        value = value.checked_mul(10)?.checked_add(u32::from(digit))?;
+    }
+    Some(value)
+}
+
+#[derive(Debug, Clone, PartialEq, Eq)]
+pub enum CalendarError {
+    InvalidDate,
+    EmptyTitle,
+    InvalidStoreFormat(String),
+    Io(String),
+}
+
+impl fmt::Display for CalendarError {
+    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
+        match self {
+            CalendarError::InvalidDate => {
+                write!(f, "invalid date; expected a real date in YYYY-MM-DD format")
+            }
+            CalendarError::EmptyTitle => write!(f, "event title must not be empty"),
+            CalendarError::InvalidStoreFormat(message) => {
+                write!(f, "invalid calendar store: {message}")
+            }
+            CalendarError::Io(message) => write!(f, "I/O error: {message}"),
+        }
+    }
+}
+
+impl std::error::Error for CalendarError {}
+
+impl From<std::io::Error> for CalendarError {
+    fn from(error: std::io::Error) -> Self {
+        CalendarError::Io(error.to_string())
+    }
+}
+
+#[derive(Debug, Clone, PartialEq, Eq)]
+pub struct Event {
+    pub date: Date,
+    pub title: String,
+}
+
+impl Event {
+    pub fn new(date: Date, title: impl Into<String>) -> Result<Self, CalendarError> {
+        let title = title.into();
+        if title.trim().is_empty() {
+            return Err(CalendarError::EmptyTitle);
+        }
+        Ok(Self { date, title })
+    }
+}
+
+impl fmt::Display for Event {
+    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
+        write!(f, "{}: {}", self.date, self.title)
+    }
+}
+
+#[derive(Debug, Default, Clone)]
+pub struct Calendar {
+    events: Vec<Event>,
+}
+
+impl Calendar {
+    pub fn new() -> Self {
+        Self::default()
+    }
+
+    pub fn add_event(
+        &mut self,
+        date: Date,
+        title: impl Into<String>,
+    ) -> Result<&Event, CalendarError> {
+        let event = Event::new(date, title)?;
+        self.events.push(event);
+        Ok(self.events.last().expect("event was just added"))
+    }
+
+    pub fn events(&self) -> &[Event] {
+        &self.events
+    }
+
+    pub fn sorted_events(&self) -> Vec<&Event> {
+        let mut events: Vec<&Event> = self.events.iter().collect();
+        events.sort_by(|left, right| {
+            left.date
+                .cmp(&right.date)
+                .then_with(|| left.title.cmp(&right.title))
+        });
+        events
+    }
+
+    pub fn events_on(&self, date: Date) -> Vec<&Event> {
+        self.sorted_events()
+            .into_iter()
+            .filter(|event| event.date == date)
+            .collect()
+    }
+
+    pub fn len(&self) -> usize {
+        self.events.len()
+    }
+
+    pub fn is_empty(&self) -> bool {
+        self.events.is_empty()
+    }
+}
+
+#[derive(Debug, Clone)]
+pub struct CalendarStore {
+    path: PathBuf,
+    calendar: Calendar,
+}
+
+impl CalendarStore {
+    pub fn open(path: impl Into<PathBuf>) -> Result<Self, CalendarError> {
+        let path = path.into();
+        let mut calendar = Calendar::new();
+        if path.exists() {
+            let contents = fs::read_to_string(&path)?;
+            for (index, line) in contents.lines().enumerate() {
+                if line.trim().is_empty() {
+                    continue;
+                }
+                let (date_text, title) = line.split_once('\t').ok_or_else(|| {
+                    CalendarError::InvalidStoreFormat(format!(
+                        "line {} is missing a tab separator",
+                        index + 1
+                    ))
+                })?;
+                let date = Date::parse(date_text).map_err(|_| {
+                    CalendarError::InvalidStoreFormat(format!(
+                        "line {} has an invalid date",
+                        index + 1
+                    ))
+                })?;
+                calendar.add_event(date, title).map_err(|_| {
+                    CalendarError::InvalidStoreFormat(format!(
+                        "line {} has an invalid title",
+                        index + 1
+                    ))
+                })?;
+            }
+        }
+        Ok(Self { path, calendar })
+    }
+
+    pub fn path(&self) -> &Path {
+        &self.path
+    }
+
+    pub fn calendar(&self) -> &Calendar {
+        &self.calendar
+    }
+
+    pub fn add_event(
+        &mut self,
+        date: Date,
+        title: impl Into<String>,
+    ) -> Result<(), CalendarError> {
+        let event = Event::new(date, title)?;
+        self.calendar.events.push(event);
+        if let Err(error) = self.save() {
+            self.calendar.events.pop();
+            return Err(error);
+        }
+        Ok(())
+    }
+
+    fn save(&self) -> Result<(), CalendarError> {
+        let mut contents = String::new();
+        for event in &self.calendar.events {
+            let title = event
+                .title
+                .replace('\n', " ")
+                .replace('\r', " ")
+                .replace('\t', " ");
+            contents.push_str(&format!("{}\t{}\n", event.date, title));
+        }
+        fs::write(&self.path, contents)?;
+        Ok(())
+    }
+}

