+use std::env;
+use std::path::PathBuf;
+use std::process;
+
+use calendar_empty::{CalendarStore, Date};
+
+fn main() {
+    if let Err(message) = run() {
+        eprintln!("error: {message}");
+        process::exit(1);
+    }
+}
+
+fn run() -> Result<(), String> {
+    let mut args = env::args().skip(1);
+    let command = match args.next() {
+        Some(command) => command,
+        None => {
+            print_usage();
+            return Ok(());
+        }
+    };
+
+    match command.as_str() {
+        "add" => {
+            let date_text = args
+                .next()
+                .ok_or_else(|| "missing date; usage: add <YYYY-MM-DD> <title>".to_string())?;
+            let title = args.collect::<Vec<_>>().join(" ");
+            if title.trim().is_empty() {
+                return Err("missing event title; usage: add <YYYY-MM-DD> <title>".to_string());
+            }
+            let date = Date::parse(&date_text).map_err(|error| error.to_string())?;
+            let mut store = CalendarStore::open(store_path()).map_err(|error| error.to_string())?;
+            store
+                .add_event(date, title.clone())
+                .map_err(|error| error.to_string())?;
+            println!("Added event: {date}: {title}");
+            Ok(())
+        }
+        "list" => {
+            let store = CalendarStore::open(store_path()).map_err(|error| error.to_string())?;
+            let events = store.calendar().sorted_events();
+            if events.is_empty() {
+                println!("No events.");
+            } else {
+                for event in events {
+                    println!("{event}");
+                }
+            }
+            Ok(())
+        }
+        "help" | "--help" | "-h" => {
+            print_usage();
+            Ok(())
+        }
+        other => Err(format!(
+            "unknown command: {other}; run with --help for usage"
+        )),
+    }
+}
+
+fn store_path() -> PathBuf {
+    env::var_os("CALENDAR_FILE")
+        .map(PathBuf::from)
+        .unwrap_or_else(|| PathBuf::from("calendar_events.txt"))
+}
+
+fn print_usage() {
+    println!("Calendar manager");
+    println!("Usage:");
+    println!("  calendar-empty add <YYYY-MM-DD> <title>");
+    println!("  calendar-empty list");
+    println!("  calendar-empty help");
+}

