@@ -0,0 +1,142 @@
+use std::fs;
+use std::path::PathBuf;
+use std::sync::atomic::{AtomicU64, Ordering};
+use std::time::{SystemTime, UNIX_EPOCH};
+
+use calendar_empty::{days_in_month, Calendar, CalendarError, CalendarStore, Date};
+
+static NEXT_ID: AtomicU64 = AtomicU64::new(0);
+
+fn temp_path(name: &str) -> PathBuf {
+    let nanos = SystemTime::now()
+        .duration_since(UNIX_EPOCH)
+        .expect("system clock should be after the unix epoch")
+        .as_nanos();
+    let id = NEXT_ID.fetch_add(1, Ordering::Relaxed);
+    std::env::temp_dir().join(format!(
+        "calendar-test-{name}-{}-{nanos}-{id}.txt",
+        std::process::id()
+    ))
+}
+
+#[test]
+fn parses_valid_date() {
+    let date = Date::parse("2024-01-01").expect("date should be valid");
+
+    assert_eq!(date.year(), 2024);
+    assert_eq!(date.month(), 1);
+    assert_eq!(date.day(), 1);
+    assert_eq!(date.to_string(), "2024-01-01");
+}
+
+#[test]
+fn handles_leap_years() {
+    assert!(Date::parse("2024-02-29").is_ok());
+    assert!(Date::parse("2000-02-29").is_ok());
+    assert!(Date::parse("1900-02-29").is_err());
+    assert!(Date::parse("2023-02-29").is_err());
+    assert_eq!(days_in_month(2024, 2), 29);
+    assert_eq!(days_in_month(2023, 2), 28);
+}
+
+#[test]
+fn rejects_invalid_dates() {
+    let invalid = [
+        "2024-13-40",
+        "2024-02-30",
+        "2023-02-29",
+        "2024-00-10",
+        "2024-01-00",
+        "2024-1-01",
+        "2024-01-1",
+        "2024/01/01",
+        "not-a-date",
+        "",
+    ];
+
+    for input in invalid {
+        assert_eq!(
+            Date::parse(input),
+            Err(CalendarError::InvalidDate),
+            "{input} should be rejected"
+        );
+    }
+}
+
+#[test]
+fn stores_and_sorts_events() {
+    let mut calendar = Calendar::new();
+    let later = Date::parse("2024-05-01").expect("date should be valid");
+    let earlier = Date::parse("2024-01-01").expect("date should be valid");
+
+    calendar
+        .add_event(later, "Zeta meeting")
+        .expect("event should be added");
+    calendar
+        .add_event(earlier, "Beta meeting")
+        .expect("event should be added");
+    calendar
+        .add_event(earlier, "Alpha meeting")
+        .expect("event should be added");
+
+    let titles: Vec<&str> = calendar
+        .sorted_events()
+        .iter()
+        .map(|event| event.title.as_str())
+        .collect();
+
+    assert_eq!(titles, vec!["Alpha meeting", "Beta meeting", "Zeta meeting"]);
+    assert_eq!(calendar.events_on(earlier).len(), 2);
+    assert_eq!(calendar.len(), 3);
+}
+
+#[test]
+fn rejects_empty_event_title() {
+    let date = Date::parse("2024-01-01").expect("date should be valid");
+    let mut calendar = Calendar::new();
+
+    assert!(matches!(
+        calendar.add_event(date, "   "),
+        Err(CalendarError::EmptyTitle)
+    ));
+}
+
+#[test]
+fn persists_events_to_store() {
+    let path = temp_path("roundtrip");
+    let date = Date::parse("2024-12-31").expect("date should be valid");
+
+    {
+        let mut store = CalendarStore::open(&path).expect("store should open");
+        store
+            .add_event(date, "New Year's Eve")
+            .expect("event should be saved");
+    }
+
+    let store = CalendarStore::open(&path).expect("store should reopen");
+    assert_eq!(store.calendar().len(), 1);
+    assert_eq!(store.calendar().events()[0].date, date);
+    assert_eq!(store.calendar().events()[0].title, "New Year's Eve");
+
+    let _ = fs::remove_file(&path);
+}
+
+#[test]
+fn rejects_malformed_store_data() {
+    let path = temp_path("invalid");
+    fs::write(&path, "2024-13-40\tBad event\n").expect("fixture should be written");
+
+    let result = CalendarStore::open(&path);
+    assert!(matches!(result, Err(CalendarError::InvalidStoreFormat(_))));
+
+    let _ = fs::remove_file(&path);
+}
+
+#[test]
+fn opens_empty_store_without_creating_file() {
+    let path = temp_path("empty");
+    let store = CalendarStore::open(&path).expect("store should open");
+
+    assert!(store.calendar().is_empty());
+    assert!(!path.exists());
+}
